import pyomo.environ as pyo

DATA = {
    # Decision media types
    "media": ["cartoon", "movie"],

    # Audience reach (millions) per commercial
    "boys": {
        "cartoon": 2,
        "movie": 4,
    },
    "girls": {
        "cartoon": 1,
        "movie": 6,
    },

    # Minimum required audience (millions)
    "boys_min": 30,
    "girls_min": 40,

    # Cost per commercial ($) per media type
    "cost": {
        "cartoon": 5000,
        "movie": 12000,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    # Sets
    model.I = pyo.Set(initialize=d["media"])

    # Decision variables: number of commercials purchased per media type
    model.x = pyo.Var(model.I, within=pyo.NonNegativeIntegers)

    # Objective: minimise total purchase cost
    def obj_rule(m):
        return sum(d["cost"][i] * m.x[i] for i in m.I)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraint: minimum boys exposure
    def boys_rule(m):
        return sum(d["boys"][i] * m.x[i] for i in m.I) >= d["boys_min"]

    model.boys_exposure = pyo.Constraint(rule=boys_rule)

    # Constraint: minimum girls exposure
    def girls_rule(m):
        return sum(d["girls"][i] * m.x[i] for i in m.I) >= d["girls_min"]

    model.girls_exposure = pyo.Constraint(rule=girls_rule)

    return model


